<script setup>
import { vCanAction } from '../../../services/permission-directives.js'
import { canArea, isCollaborator } from '../../../services/access.js'
import { getStoredUser } from '../../../services/tokens.js'
import { vAuthHref } from '../authenticated-media.js'
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import AIUsageDetails from '../components/AIUsageDetails.vue'
import { api, formatDate, messageOf, socket } from '../services.js'

const items = ref([]), level = ref(''), scope = ref(''), search = ref(''), loading = ref(false), paused = ref(false), toast = ref(''), consoleBox = ref(null), expanded = ref('')
const usage = ref(null), collectSeconds = ref(3), runtimeSettings = ref(null), jsonOpen = ref(false)
const amount = (value, currency) => value == null ? "Indisponível" : Number(value).toLocaleString("pt-BR", { style: "currency", currency })
async function loadUsage() { if (!canArea(getStoredUser(), 'web_integrations')) return; try { usage.value = (await api.get("/integrations/openai/usage")).data } catch (error) { show(messageOf(error)) } }
async function saveWindow() { try { await api.put("/settings", { runtime: { collectWindowMs: Math.round(collectSeconds.value * 1000) } }); show("Intervalo aplicado ao bot e simulador.") } catch (error) { show(messageOf(error)) } }
const payments = ref({ orders: [], events: [] })
let paymentTimer
const money = cents => (Number(cents || 0) / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
async function loadPayments() { if (!canArea(getStoredUser(), 'web_integrations')) return; try { payments.value = (await api.get('/integrations/infinitepay/monitor')).data } catch (cause) { show(messageOf(cause)) } }
function show(value) { toast.value = value; setTimeout(() => { if (toast.value === value) toast.value = '' }, 3200) }
async function load() { loading.value = true; try { items.value = (await api.get('/logs', { params: { limit: 150, level: level.value || undefined, scope: scope.value || undefined, search: search.value || undefined } })).data.items.reverse(); await nextTick(); scrollBottom() } catch (cause) { show(messageOf(cause)) } finally { loading.value = false } }
function scrollBottom() { if (consoleBox.value && !paused.value) consoleBox.value.scrollTop = consoleBox.value.scrollHeight }
function receive(entry) {
  if (paused.value) return
  if (level.value && entry.level !== level.value) return
  if (scope.value && entry.scope !== scope.value) return
  if (search.value && !entry.message.toLowerCase().includes(search.value.toLowerCase())) return
  items.value.push(entry); if (items.value.length > 300) items.value.shift(); nextTick(scrollBottom)
}
async function clear() { if (!confirm('Limpar todos os registros visíveis e armazenados?')) return; try { await api.delete('/logs'); items.value = []; show('Logs limpos.') } catch (cause) { show(messageOf(cause)) } }
onMounted(() => { load(); loadPayments(); loadUsage(); (canArea(getStoredUser(), 'web_settings') ? api.get("/settings") : Promise.resolve({data:{runtime:{}}})).then(response => { runtimeSettings.value = response.data; collectSeconds.value = (response.data.runtime.collectWindowMs || 3000) / 1000 }).catch(error => show(messageOf(error))); paymentTimer = setInterval(() => { loadPayments(); loadUsage() }, 15000); socket.on('log:created', receive) })
onBeforeUnmount(() => { clearInterval(paymentTimer); socket.off('log:created', receive) })
</script>

<template>
  <section><AIUsageDetails v-if="canArea(getStoredUser(), 'web_integrations')" :conversations="usage?.byConversation||[]" :load="async params=>(await api.get('/integrations/openai/usage/details',{params})).data" />
    <div class="page-head"><div><span class="eyebrow">Observabilidade em tempo real</span><h1>Logs de execução</h1><p>Acompanhe cada mensagem, nó do fluxo, chamada de API, fila e reconexão com contexto preciso.</p></div><button :class="['btn',paused?'':'secondary']" @click="paused=!paused">{{ paused ? '▶ Retomar tempo real' : 'Ⅱ Pausar tela' }}</button></div>
    <div v-if="canArea(getStoredUser(), 'web_integrations')" class="card payment-monitor"><div class="payment-monitor__head"><div><span class="eyebrow">INFINITEPAY</span><h2>Links e pagamentos</h2></div><button class="btn secondary" @click="loadPayments">Atualizar</button></div><div class="payment-monitor__counts"><span>Links {{ payments.orders.length }}</span><span>Pagos {{ payments.orders.filter(item => item.status === 'paid').length }}</span><span>Recusados {{ payments.orders.filter(item => item.status === 'declined').length }}</span></div><div class="payment-monitor__items"><article v-for="order in payments.orders.slice(0, 12)" :key="order.orderNsu"><strong>{{ order.chatId?.displayName || order.chatId?.phone || order.orderNsu }}</strong><span>{{ money(order.amountCents) }} · {{ order.status }}</span><a v-if="order.checkoutUrl" v-auth-href="order.checkoutUrl" target="_blank" rel="noopener noreferrer">Checkout ↗</a><button v-can-action="'web_integrations.create'" v-if="order.status === 'pending'" class="btn secondary" @click="async () => { if (confirm('Marcar como recusado após conferir a InfinitePay?')) { try { await api.post(`/integrations/infinitepay/orders/${order.orderNsu}/decline`); await loadPayments() } catch (error) { show(messageOf(error)) } } }">Marcar recusado</button></article></div><button class="btn secondary" @click="jsonOpen = true">Ver logs JSON do webhook ({{ payments.events.length }})</button></div>
    <div v-if="jsonOpen" class="modal-backdrop" role="dialog" aria-modal="true" aria-label="Logs InfinitePay"><section class="card json-dialog"><header><h2>Eventos InfinitePay</h2><button class="icon-button" aria-label="Fechar logs" @click="jsonOpen = false">×</button></header><p v-if="!payments.events.length">Nenhum evento recebido.</p><article v-for="event in payments.events" :key="event._id"><b>{{ formatDate(event.createdAt) }} · {{ event.state }}</b><pre>{{ JSON.stringify(event.payload, null, 2) }}</pre></article></section></div>
<div v-can-action="'web_settings.configure'" class="card payment-monitor"><h2>Agrupamento de mensagens</h2><div class="field"><label>Espera após a última mensagem (segundos)</label><input v-model.number="collectSeconds" type="number" min="0.2" max="15" step="0.1"></div><p>O mesmo intervalo é usado pelo bot e simulador.</p><button class="btn" :disabled="!runtimeSettings || collectSeconds < 0.2 || collectSeconds > 15" @click="saveWindow">Salvar intervalo</button></div>
<div v-if="usage" class="card payment-monitor"><h2>Consumo da IA · últimos {{ usage.periodDays }} dias</h2><div class="usage-totals"><strong>{{ usage.totals.totalTokens.toLocaleString('pt-BR') }} tokens</strong><strong>{{ amount(usage.totals.estimatedUsd, 'USD') }}</strong><strong>{{ amount(usage.totals.estimatedBrl, 'BRL') }}</strong></div><p>Valores estimados. Cotação semanal do Banco Central: {{ usage.exchange.rate || 'indisponível' }} · {{ formatDate(usage.exchange.fetchedAt) }}</p><div class="usage-table"><article v-for="row in usage.byConversation" :key="row.chatId"><div><b>{{ row.name }}</b><small>{{ row.phone }} · {{ row.models.join(', ') }}</small></div><span>{{ row.totalTokens.toLocaleString('pt-BR') }} tokens</span><span>{{ amount(row.estimatedUsd, 'USD') }}</span><span>{{ amount(row.estimatedBrl, 'BRL') }}</span></article><p v-if="!usage.byConversation.length">Nenhum consumo registrado neste período.</p></div></div>
<div class="card log-toolbar"><select v-model="level" @change="load"><option value="">Todos os níveis</option><option value="info">Informações</option><option value="warn">Avisos</option><option value="error">Erros</option><option value="debug">Debug</option></select><select v-model="scope" @change="load"><option value="">Todos os módulos</option><option value="whatsapp">WhatsApp</option><option value="flow">Fluxos</option><option value="action">Ações/API</option><option value="queue">Fila</option><option value="api">Painel/API</option><option value="process">Processo</option></select><input v-model="search" class="search" placeholder="Buscar mensagem…" @keyup.enter="load"><button class="btn secondary" @click="load">Atualizar</button><button v-if="!isCollaborator(getStoredUser())" class="btn danger" @click="clear">Limpar</button></div>
    <div ref="consoleBox" class="card log-console">
      <div v-if="loading && !items.length" class="empty dark">Carregando console…</div>
      <div v-else-if="!items.length" class="empty dark"><b>Nenhum evento encontrado</b><span>Os próximos eventos aparecerão aqui automaticamente.</span></div>
      <article v-for="entry in items" v-else :key="entry._id" :class="['log-line',entry.level]" @click="expanded=expanded===entry._id?'':entry._id">
        <time>{{ formatDate(entry.createdAt, true) }}</time><span class="level">{{ entry.level }}</span><span class="scope">{{ entry.scope }}</span><span class="event">{{ entry.event }}</span><p>{{ entry.message }}</p><em v-if="entry.durationMs != null">{{ entry.durationMs }} ms</em>
        <pre v-if="expanded===entry._id && entry.context">{{ JSON.stringify(entry.context,null,2) }}</pre>
      </article>
    </div>
    <div class="log-foot"><span><i class="live-dot"></i>{{ paused ? 'Visualização pausada' : 'Recebendo eventos em tempo real' }}</span><small>Segredos e cabeçalhos sensíveis são ocultados antes do armazenamento.</small></div>
    <div v-if="toast" class="toast">{{ toast }}</div>
  </section>
</template>

<style scoped>
.log-toolbar.card select{background:#082123;color:#e6fff6;border-color:#315b50}.payment-monitor .payment-monitor__counts{color:#95d6c4}
.log-toolbar{display:grid;grid-template-columns:170px 180px minmax(180px,1fr) auto auto;gap:8px;padding:11px;margin-bottom:12px}.log-toolbar select{padding:9px;border:1px solid var(--line);border-radius:9px;background:white}.log-console{height:calc(100vh - 285px);min-height:500px;padding:10px;overflow:auto;color:#d9eee9;background:#0d211d;font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.log-line{display:grid;grid-template-columns:130px 55px 82px 120px minmax(180px,1fr) auto;gap:8px;align-items:start;padding:8px;border-bottom:1px solid rgba(255,255,255,.06);font-size:.66rem;cursor:pointer}.log-line:hover{background:rgba(255,255,255,.035)}.log-line time{color:#78968e}.log-line .level{font-weight:800;text-transform:uppercase}.log-line.info .level{color:#64d9bd}.log-line.warn .level{color:#f5c768}.log-line.error .level{color:#ff7f91}.log-line.debug .level{color:#83a8ff}.scope{color:#acd3ca}.event{color:#82a49c}.log-line p{margin:0;overflow-wrap:anywhere}.log-line em{color:#708f87;font-style:normal}.log-line pre{grid-column:1/-1;margin:6px 0 0;padding:10px;border-radius:8px;overflow:auto;color:#c7ded8;background:#071713;white-space:pre-wrap}.empty.dark{color:#718f87}.empty.dark b{color:#c7e3dc}.log-foot{display:flex;justify-content:space-between;padding:9px 4px;color:#71837e;font-size:.65rem}.log-foot span{display:flex;align-items:center;gap:7px}.live-dot{width:7px;height:7px;border-radius:50%;background:#36d0ad;box-shadow:0 0 0 4px rgba(54,208,173,.12)}@media(max-width:900px){.log-toolbar{grid-template-columns:1fr 1fr}.log-toolbar .search{grid-column:1/-1}.log-console{height:calc(100vh - 360px)}.log-line{grid-template-columns:105px 48px 70px 1fr}.log-line .event{display:none}.log-line p{grid-column:2/-1}.log-foot{align-items:flex-start;flex-direction:column;gap:5px}}@media(max-width:560px){.log-toolbar{grid-template-columns:1fr}.log-toolbar .search{grid-column:auto}.log-line{grid-template-columns:1fr auto}.log-line time,.log-line .scope{display:none}.log-line p{grid-column:1/-1}}
.payment-monitor{padding:16px;margin-bottom:14px}.payment-monitor__head,.payment-monitor__counts,.payment-monitor__items article{display:flex;align-items:center;justify-content:space-between;gap:12px}.payment-monitor__head h2{margin:0;font-size:1rem}.payment-monitor__counts{justify-content:flex-start;flex-wrap:wrap;margin:10px 0;color:#386a5d}.payment-monitor__items{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:7px;max-height:190px;overflow:auto}.payment-monitor__items article{flex-wrap:wrap;padding:8px;border:1px solid var(--line);border-radius:7px;font-size:.7rem}.payment-monitor__items a{color:#087e67}.payment-monitor details{margin-top:10px}.payment-monitor pre{max-height:240px;overflow:auto;padding:9px;background:#0d211d;color:#d9eee9;white-space:pre-wrap;overflow-wrap:anywhere}
.modal-backdrop{position:fixed;inset:0;z-index:200;display:grid;place-items:center;padding:16px;background:#041514bb}.json-dialog{width:min(800px,100%);max-height:90dvh;padding:20px;overflow:auto}.json-dialog header{display:flex;align-items:center;justify-content:space-between}.json-dialog pre{overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:#061718;padding:15px}.usage-totals{display:flex;flex-wrap:wrap;gap:25px;margin:20px 0}.usage-table{max-height:350px;overflow:auto}.usage-table article{display:grid;grid-template-columns:minmax(100px,1fr) repeat(3,auto);gap:18px;border-bottom:1px solid var(--line);padding:12px 0;font-size:12px}.usage-table small{display:block;color:var(--muted);overflow-wrap:anywhere}.payment-monitor h2{font-size:18px}.payment-monitor p{color:var(--muted);font-size:12px}.payment-monitor .field{max-width:300px;margin:15px 0}@media(max-width:600px){.usage-table article{grid-template-columns:1fr 1fr;gap:8px}}
</style>

<style scoped>
.json-dialog pre{color:#d9eee9}.payment-monitor .payment-monitor__counts{color:var(--primary-dark)}
</style>
